 "content": "from collections import deque


def transform(grid):
    """Remove the connected nonzero object containing exactly two 9 cells."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            nines = 0
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                nines += grid[y][x] == 9
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0
                            and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            if nines == 2:
                for y, x in cells:
                    out[y][x] = 0
    return out
